//! Parts generated by `kicad_part!` from the test libraries of `crates/kicad_lib/tests/fixtures`.

use std::collections::BTreeMap;

use cuprite_wire::{
    circuit::CircuitBuilder,
    kicad::{KicadPartInfo, KicadPinInfo, LibId, PartFlags, PinType},
    kicad_part,
    naming::NetLabel,
    parts::Part,
    spice::{ModelSource, SpiceElement, SpicePartInfo},
};

kicad_part! {
    /// A resistor in an 0603 package.
    pub struct Resistor {
        symbol: "test:R",
        footprint: "test:R_0603",
        value: param,
        symbol_dir: "crates/kicad_lib/tests/fixtures/symbols",
        footprint_dir: "crates/kicad_lib/tests/fixtures/footprints",
    }
}

kicad_part! {
    /// A dual amplifier with an exposed pad connected to V-.
    struct DualAmp {
        symbol: "test:DUAL_AMP",
        footprint: "test:SOIC-8-EP",
        pins: { "1" => "out_a", "7" => "out_b", "9" => "ep" },
        extra_pads: ["9"],
        internal_connections: [["4", "ep"]],
        fields: { "MPN" => "DA-1" },
        symbol_dir: "crates/kicad_lib/tests/fixtures/symbols",
        footprint_dir: "crates/kicad_lib/tests/fixtures/footprints",
    }
}

kicad_part! {
    /// A regulator: its footprint comes from the symbol, and it is excluded from the simulation.
    struct Regulator {
        symbol: "test:REG",
        symbol_dir: "crates/kicad_lib/tests/fixtures/symbols",
        footprint_dir: "crates/kicad_lib/tests/fixtures/footprints",
    }
}

kicad_part! {
    struct Amp {
        symbol: "test:SIM_AMP",
        footprint: none,
        sim_model: inline,
        symbol_dir: "crates/kicad_lib/tests/fixtures/symbols",
        sim_library_dir: "crates/kicad_lib/tests/fixtures",
    }
}

fn strings(s: &[&str]) -> Vec<String> {
    s.iter().map(|s| s.to_string()).collect()
}

#[test]
fn test_resistor() {
    let r = Resistor::new("10k");
    assert_eq!(r.get_ref_base_name(), "R");
    assert_eq!(r.pin_ids(), strings(&["1", "2"]));
    assert_eq!(r.value(), "10k");
    assert!(r.internal_connections().is_empty());
    assert_eq!(
        r.kicad(),
        Some(KicadPartInfo {
            footprint: Some("test:R_0603".parse().unwrap()),
            pins: BTreeMap::from([
                ("1".into(), KicadPinInfo::new("1", None, PinType::Passive)),
                ("2".into(), KicadPinInfo::new("2", None, PinType::Passive)),
            ]),
            lib_source: Some(LibId::new("test", "R").unwrap()),
            fields: vec![],
            flags: PartFlags::default(),
        })
    );
    assert_eq!(r.spice(), Some(SpicePartInfo::element(SpiceElement::new('R', ["1", "2"], "10k"))));
}

#[test]
fn test_dual_amp() {
    let amp = DualAmp::new();
    assert_eq!(DualAmp::PINS, ["out_a", "2", "3", "4", "5", "6", "out_b", "8", "ep"]);
    assert_eq!(DualAmp::OUT_A, "out_a");
    assert_eq!(amp.value(), "DUAL_AMP");
    assert_eq!(amp.get_ref_base_name(), "U");
    assert_eq!(amp.internal_connections(), vec![strings(&["4", "ep"])]);
    let info = amp.kicad().unwrap();
    assert_eq!(info.pins["out_a"], KicadPinInfo::new("1", None, PinType::Output));
    assert_eq!(info.pins["4"], KicadPinInfo::new("4", Some("V-"), PinType::PowerIn));
    assert_eq!(info.pins["ep"], KicadPinInfo::new("9", None, PinType::Passive));
    assert_eq!(info.fields, vec![("MPN".to_string(), "DA-1".to_string())]);
    assert!(info.check_pins(&amp.pin_ids()).is_empty());
    assert_eq!(amp.spice(), None);
}

#[test]
fn test_regulator() {
    let reg = Regulator;
    let info = reg.kicad().unwrap();
    assert_eq!(info.footprint, Some("test:SOT-223".parse().unwrap()));
    assert!(info.flags.exclude_from_bom);
    assert_eq!(reg.internal_connections(), vec![strings(&["2", "4"])]);
    assert_eq!(reg.spice(), Some(SpicePartInfo::Excluded));
}

#[test]
fn test_inline_subcircuit() {
    let amp = Amp::default();
    assert_eq!(amp.kicad().unwrap().footprint, None);
    let Some(SpicePartInfo::Elements { elements, unused_pins }) = amp.spice() else {
        panic!("{:?}", amp.spice())
    };
    assert_eq!(unused_pins, strings(&["6"]));
    assert_eq!(elements[0].nodes, strings(&["3", "2", "5", "4", "1"]));
    assert_eq!(elements[0].args, "amp GAIN=100");
    let names: Vec<_> = elements[0]
        .models
        .iter()
        .map(|m| match m {
            ModelSource::Inline { name, .. } => name.as_str(),
            ModelSource::Include { .. } => panic!(),
        })
        .collect();
    assert_eq!(names, ["amp", "clamp"]);
}

/// The generated parts work in a circuit exported to KiCad and SPICE.
#[test]
fn test_export() {
    let mut circuit = CircuitBuilder::new();
    let amp = circuit.instantiate_part_named("amp", Box::new(DualAmp::new()));
    let r1 = circuit.instantiate_part_named("r1", Box::new(Resistor::new("10k")));
    let r2 = circuit.instantiate_part_named("r2", Box::new(Resistor::new("1k")));
    circuit.connect(amp["out_a"], r1["1"]);
    circuit.connect(r1["2"], amp["2"]);
    circuit.connect(amp["2"], r2["1"]);
    circuit.label(r2["2"], NetLabel::global("GND"));
    circuit.label(amp["ep"], NetLabel::global("GND"));
    circuit.label(amp["3"], NetLabel::local("IN"));
    circuit.label(amp[DualAmp::OUT_A], NetLabel::local("OUT"));
    let netlist = circuit.build(&()).to_netlist().unwrap();
    let mut out = Vec::new();
    netlist.to_kicad().unwrap().write(&mut out).unwrap();
    let text = String::from_utf8(out).unwrap();
    assert!(text.contains("(libsource (lib \"test\") (part \"DUAL_AMP\")"), "{text}");
    // V- (pad 4) and the exposed pad (9) are on GND through the internal connection.
    assert!(text.contains("(node (ref \"U1\") (pin \"4\") (pinfunction \"V-\") (pintype \"power_in\"))"), "{text}");
    // The amplifier has no SPICE model.
    assert!(netlist.to_spice().is_err());
}
